})

describe('handle', () => {
  it('sends correctly mapped fields to Discord webhook on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/webhooks/test-webhook-id/test-webhook-token')
        ? jsonResponse({ id: 'msg-123' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: AirtablePayloadsResponse = {
      payloads: [
        {
          id: 'rec111',
          baseTransactionNumber: 1,
          timestamp: '2023-01-01T00:00:00.000Z',
          data: {
            recordId: 'rec111',
            record: {
              id: 'rec111',
              createdTime: '2023-01-01T12:00:00.000Z',
              fields: {
                Name: 'Alice',
                Email: 'alice@example.com',
                Age: 30
              }
            }
          }
        }
      ]
    }

    const config: ConnectorConfig = {
      discordWebhookId: 'test-webhook-id',
      discordWebhookToken: 'test-webhook-token',
      fetch
    }

    const result = await handle(payload, config)

    expect(result.messageIds).toEqual(['msg-123'])
    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://discord.com/api/webhooks/test-webhook-id/test-webhook-token?wait=true')
    expect(call.json).toEqual({
      content: 'rec111',
      embeds: [
        {
          title: '2023-01-01T12:00:00.000Z',
          description: 'Name: Alice\nEmail: alice@example.com\nAge: 30'
        }
      ]
    })
    expect(call.headers.get('content-type')).toBe('application/json')
  })

  it('uses token in URL for authorization (no auth header)', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/webhooks/wh-id/wh-token') ? jsonResponse({ id: 'm1' }, 200) : jsonResponse({}, 404)
    )

    const payload: AirtablePayloadsResponse = {
      payloads: [
        {
          id: 'rec1',
          baseTransactionNumber: 1,
          timestamp: '2023-01-01T00:00:00.000Z',
          data: {
            recordId: 'rec1',
            record: { id: 'rec1', createdTime: '2023-01-01T00:00:00.000Z', fields: { Foo: 'bar' } }
          }
        }
      ]
    }

    await handle(payload, { discordWebhookId: 'wh-id', discordWebhookToken: 'wh-token', fetch })

    expect(calls[0].url).toContain('/webhooks/wh-id/wh-token')
    expect(calls[0].headers.get('authorization')).toBeNull()
  })

  it('maps record id to content and createdTime to embed title', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'm1' }, 200))

    const payload: AirtablePayloadsResponse = {
      payloads: [
        {
          id: 'recXYZ',
          baseTransactionNumber: 1,
          timestamp: '2023-01-01T00:00:00.000Z',
          data: {
            recordId: 'recXYZ',
            record: { id: 'recXYZ', createdTime: '2023-05-05T10:30:00.000Z', fields: { A: '1' } }
          }
        }
      ]
    }

    await handle(payload, { discordWebhookId: 'id', discordWebhookToken: 'tok', fetch })

    expect(calls[0].json).toEqual({
      content: 'recXYZ',
      embeds: [{ title: '2023-05-05T10:30:00.000Z', description: 'A: 1' }]
    })
  })

